CodeAssembler& CodeAssemblerFns2::pop(AsmRegisterSegment op0) {
	Code code;
	if (op0.register_() == Register::FS) {
		if (bitness() == 64) {
			code = Code::Popq_FS;
		} else if (bitness() >= 32) {
			code = Code::Popd_FS;
		} else {
			code = Code::Popw_FS;
		}
	} else if (op0.register_() == Register::GS) {
		if (bitness() == 64) {
			code = Code::Popq_GS;
		} else if (bitness() >= 32) {
			code = Code::Popd_GS;
		} else {
			code = Code::Popw_GS;
		}
	} else if (op0.register_() == Register::ES) {
		if (bitness() >= 32) {
			code = Code::Popd_ES;
		} else {
			code = Code::Popw_ES;
		}
	} else if (op0.register_() == Register::SS) {
		if (bitness() >= 32) {
			code = Code::Popd_SS;
		} else {
			code = Code::Popw_SS;
		}
	} else if (op0.register_() == Register::DS) {
		if (bitness() >= 32) {
			code = Code::Popd_DS;
		} else {
			code = Code::Popw_DS;
		}
	} else {
		return set_error("pop: invalid operands");
	}
	return add_instr(Instruction::with1(code, op0.register_()));
}

CodeAssembler& CodeAssemblerFns2::pop(AsmMemoryOperand op0) {
	Code code;
	if (op0.size() == MemoryOperandSize::Qword) {
		code = Code::Pop_rm64;
	} else if (op0.size() == MemoryOperandSize::Dword) {
		code = Code::Pop_rm32;
	} else if (op0.size() == MemoryOperandSize::Word) {
		code = Code::Pop_rm16;
	} else {
		return set_error("pop: invalid operands");
	}
	return add_instr(Instruction::with1(code, to_memory_operand(op0)));
}

