CodeAssembler& CodeAssemblerFns2::shl(AsmMemoryOperand op0, AsmRegister8 op1) {
	Code code;
	if (op0.size() == MemoryOperandSize::Qword) {
		code = Code::Shl_rm64_CL;
	} else if (op0.size() == MemoryOperandSize::Dword) {
		code = Code::Shl_rm32_CL;
	} else if (op0.size() == MemoryOperandSize::Word) {
		code = Code::Shl_rm16_CL;
	} else if (op0.size() == MemoryOperandSize::Byte) {
		code = Code::Shl_rm8_CL;
	} else {
		return set_error("shl: invalid operands");
	}
	return add_instr(Instruction::with2(code, to_memory_operand(op0), op1.register_()));
}

CodeAssembler& CodeAssemblerFns2::shl(AsmRegister8 op0, std::int32_t op1) {
	const Code code = op1 == 1 ? Code::Shl_rm8_1 : Code::Shl_rm8_imm8;
	return add_instr(Instruction::with2(code, op0.register_(), op1));
}

