CodeAssembler& CodeAssemblerFns2::shl(AsmRegister64 op0, std::int32_t op1) {
	const Code code = op1 == 1 ? Code::Shl_rm64_1 : Code::Shl_rm64_imm8;
	return add_instr(Instruction::with2(code, op0.register_(), op1));
}

CodeAssembler& CodeAssemblerFns2::shl(AsmMemoryOperand op0, std::int32_t op1) {
	Code code;
	if (op1 == 1) {
		if (op0.size() == MemoryOperandSize::Qword) {
			code = Code::Shl_rm64_1;
		} else if (op0.size() == MemoryOperandSize::Dword) {
			code = Code::Shl_rm32_1;
		} else if (op0.size() == MemoryOperandSize::Word) {
			code = Code::Shl_rm16_1;
		} else if (op0.size() == MemoryOperandSize::Byte) {
			code = Code::Shl_rm8_1;
		} else {
			return set_error("shl: invalid operands");
		}
	} else if (op0.size() == MemoryOperandSize::Qword) {
		code = Code::Shl_rm64_imm8;
	} else if (op0.size() == MemoryOperandSize::Dword) {
		code = Code::Shl_rm32_imm8;
	} else if (op0.size() == MemoryOperandSize::Word) {
		code = Code::Shl_rm16_imm8;
	} else if (op0.size() == MemoryOperandSize::Byte) {
		code = Code::Shl_rm8_imm8;
	} else {
		return set_error("shl: invalid operands");
	}
	return add_instr(Instruction::with2(code, to_memory_operand(op0), op1));
}

